package cmd

import (
	"strings"
	"testing"

	"github.com/LarsArtmann/gogenfilter/v3"
)

// realisticContent mimics a regular Go source file: ~2KB, no generation markers.
// This is the overwhelmingly common case (>95% of files in a typical Go repo).
var realisticContent = []byte(strings.Repeat("package main\n\nfunc f() error {\n\treturn nil\n}\n", 50))

// generatedContent mimics a templ-generated file with the standard header.
var generatedContent = []byte(
	"// Code generated by templ - DO NOT EDIT.\npackage x\nvar _ = templ.Component\n" + strings.Repeat(
		"func f() {}\n",
		100,
	),
)

// BenchmarkMatchedGeneratedCategory_RegularFile measures the fast-path: a
// regular file without any "Code generated" header should bail out after a
// single bytes.Contains with zero allocations.
func BenchmarkMatchedGeneratedCategory_RegularFile(b *testing.B) {
	b.ReportAllocs()
	b.ResetTimer()

	for b.Loop() {
		matchedGeneratedCategory(realisticContent)
	}
}

// BenchmarkMatchedGeneratedCategory_GeneratedFile measures the full marker scan
// for a file that IS generated.
func BenchmarkMatchedGeneratedCategory_GeneratedFile(b *testing.B) {
	b.ReportAllocs()
	b.ResetTimer()

	for b.Loop() {
		matchedGeneratedCategory(generatedContent)
	}
}

// BenchmarkAllowsContent_RegularFile measures the include-path fast-exit: a
// regular file without the header should return false without any string
// conversion.
func BenchmarkAllowsContent_RegularFile(b *testing.B) {
	includes := generatorIncludes{gogenfilter.ReasonSQLC: true, gogenfilter.ReasonTempl: true}

	b.ReportAllocs()
	b.ResetTimer()

	for b.Loop() {
		includes.allowsContent(realisticContent)
	}
}

// BenchmarkCategoryIncluded measures the reason→bool lookup.
func BenchmarkCategoryIncluded(b *testing.B) {
	includes := generatorIncludes{gogenfilter.ReasonTempl: true}

	b.ReportAllocs()
	b.ResetTimer()

	for b.Loop() {
		includes.categoryIncluded(gogenfilter.ReasonTempl)
	}
}
